#ifndef SD_PARSER_H
#define SD_PARSER_H

#include <stdint.h>
#include "ff.h"
#include "xstatus.h"

#define SD_MAX_MSG_BYTES    16384U

/* 40-byte packed header generated by scripts/preprocess_rsp.py */
typedef struct __attribute__((packed)) {
    uint32_t bit_len;
    uint32_t byte_len;
    uint32_t golden_md[8];
} SHA256_VecHeader_t;

typedef struct {
    uint32_t bit_len;
    uint32_t byte_len;
    uint32_t golden_md[8];
    uint8_t  msg[SD_MAX_MSG_BYTES] __attribute__((aligned(64)));
} SHA256_TestVector_t;

int  sd_mount(void);
void sd_unmount(void);
int  sd_open_file(FIL *fil, const char *filepath);
void sd_close_file(FIL *fil);
int  sd_read_next_vector(FIL *fil, SHA256_TestVector_t *vec);

#endif /* SD_PARSER_H */